#!/bin/bash
# Concept sheets for the planet's regions and factions, generated through the Codex CLI (ChatGPT image generation).
# These are for agreeing the look of each faction; the per-creature image-to-3D references come later (gen_refs.sh).
CX="/c/Program Files/WindowsApps/OpenAI.Codex_26.1106.6628.0_x64__2p2nqsd0c76g0/app/resources/codex.exe"
cd "$(dirname "$0")"
mkdir -p concepts
cd concepts
COMMON="Match the rendering style of the attached style sheet exactly (stylized 3D game art, saturated colour, clean readable shapes, soft studio lighting on the characters). Lay it out as a game concept sheet on a dark navy background, landscape 16:9: on the left two thirds, three full-body creatures standing side by side in a line-up, small to large, each clearly separated; on the right third, one tall environment painting of their home region with the same creatures tiny in the distance. No text, no labels, no logos, no borders."
gen () { # name prompt
  [ -f "$1.png" ] && { echo "skip $1"; return; }
  "$CX" exec --skip-git-repo-check -s workspace-write "Use your built-in image generation tool to generate one image: $2 $COMMON Save the resulting PNG into the current directory as $1.png. Reply with only the saved file path." -i ../refs/style_sheet.webp < /dev/null > "$1.log" 2>&1
  [ -f "$1.png" ] && echo "ok $1" || echo "FAIL $1"
}
gen sporekin "An alien faction called the Sporekin, living fungus creatures of a giant mushroom forest. Palette: orange and amber caps, purple stalk-flesh, teal glowing spores. Creature 1: a small scuttling mushroom-capped crawler on four root legs. Creature 2: a tall slow shambling fungal giant with a huge orange cap for a head, thick bark-like purple arms and glowing teal spore sacs on its back. Creature 3: a stationary bloated spore-mother rooted to the ground, with vents puffing teal spore clouds. Environment: a dim forest of enormous orange funnel mushrooms with purple trunks, hanging teal spore mist, shafts of light, pools on the forest floor." &
gen shardback "An alien faction called the Shardbacks, armoured beasts of a volcanic crystal desert. Palette: black basalt hide, glowing ember-red and amber crystals, hot orange cracks. Creature 1: a low fast four-legged hound with a row of red crystal spines along its back. Creature 2: a heavy rhino-like charging beast with a massive black armoured head plate covering its whole front and exposed glowing crystals on its rump. Creature 3: a hunched crystal-backed artillery beast with a cluster of long amber crystal spikes it launches from its back. Environment: a desert of black glassy dunes and tall red crystal formations under an orange sky, lava glowing in cracks, heat haze." &
gen galewing "An alien faction called the Galewings, flying creatures of storm-swept mountain peaks. Palette: pale ivory and sky-blue bodies, gold crests, white-blue lightning glow. Creature 1: a small darting manta-like flyer with a whip tail. Creature 2: a lean winged raptor-like diver with four wings, a long gold beak-blade and talons, shown hovering. Creature 3: a large floating jellyfish-like storm caller with a translucent blue gas bell, gold frills and crackling lightning tendrils. Environment: towering pale stone peaks and floating rock islands above a sea of cloud, dark storm clouds with lightning, wind streaks, the flyers circling." &
gen warden "An alien faction called the Wardens, ancient stone-and-light machines guarding sunken ruins. Palette: matte black and dark grey carved stone, white and pale-green hard light, thin gold inlay. Creature 1: a small floating diamond-shaped sentry drone with a single green eye. Creature 2: a tall slender bipedal stone sentinel with a hovering detached head, a hard-light shield on one arm and a beam lance on the other. Creature 3: a massive floating monolith construct made of separate black stone blocks orbiting a bright green core. Environment: a huge half-flooded underground hall of black geometric ruins, glowing green glyph lines on the walls, hard-light bridges, shallow turquoise water on the floor." &
wait
echo ALLDONE
